    rr=[r for r in rows if r['category']==cat];im=Image.new('RGB',(1280,400*3),'white');d=ImageDraw.Draw(im)
    for i,r in enumerate(rr):
        x=i%2*640;y=i//2*400
        d.text((x+5,y+5),r['sample']+' | '+r['role'],fill='black')
        if not r.get('camera_copy'):continue
        im.paste(Image.open(r['camera_copy']),(x,y+30))
        pts=[(x+a,y+30+b) for a,b in P[r['sample']]]
        d.line(pts+[pts[0]],fill=(255,80,100),width=2)
    im.save(OUT/(cat+'-contours.jpg'),quality=96)
